    "Name": "CommonCacheScripts",
    "Key": "ContentManagement",
    "ResourceKey": "ContentManagement",
    "Script": "CommonCacheScripts = {
    init: async function (app, container) {
        app = app || session.app;
        container = container || $(".component[name=CommonCacheScripts]");
        var scriptData = await CommonCacheScripts.getDataSource("ContentManagement/CommonObject/Latest()?type=ContentManagement/Script&$orderby=Name asc");
        await CommonCacheScripts.setupScriptGrid(scriptData, container);
    },

    getDataSource(url) {
        return new kendo.data.DataSource({
            transport: {
                read: { url: api.apiRoot + url, dataType: "json" }
            },
            pageSize: 50,
            schema: {
                data: function (response) {
                    for (let i = 0; i < response.value.length; i++) {
                        response.value[i].CreatedOn = new Date(response.value[i].CreatedOn);
                        response.value[i].LastUpdated = new Date(response.value[i].LastUpdated);
                        response.value[i].Entity = JSON.parse(response.value[i].Json);
                    }
                    return response.value;
                },
                total: (response) => response.value.length
            },
            group: { field: "Key" }
        });
    },

    setupScriptGrid: async function (ds, container) {
        var cacheGrid = new GridWidget(container, ds);
        cacheGrid.columns = [
            { field: "Key", title: "[resource_shortdisplayname[key]]", width: "[theme[columns.small]]", width: 100},
            { field: "Name", title: "[resource_shortdisplayname[name]]", width: 600 },
            { field: "LastUpdated", title: "[resource_displayname[lastupdated]]", type: "date", format: "{0:g}", width: "[theme[columns.small]]", width: 160},
            { field: "LastUpdatedBy", title: "[resource_displayname[lastupdatedby]]", width: "[theme[columns.small]]", width: 300 },
        ];
        cacheGrid.groupable = false;
        cacheGrid.filterable = true;
        cacheGrid.editable = false;
        cacheGrid.pageable = true;
        cacheGrid.detailTemplate = kendo.template($("[name=scriptDetails]", container).html());

        cacheGrid.detailExpand = function (e) {
            var container = $(e.detailRow);

            if (container.find(".monaco-editor").length === 0) {
                var scriptEntity = cacheGrid.dataItem(e.masterRow).Entity;
                var scriptEditorDiv = container.find("div[name=script]")[0];

                var script = new JavaScriptMonacoEditor(scriptEditorDiv, { code: scriptEntity.Content });
                script.onChange = () => {
                    scriptEntity.Content = script.getValue();
                };
                script.init();
            }
        };

        cacheGrid.commands.push({ name: "viewVersions", icon: "k-i-clock", text: "[resource_displayname[viewversions]]" });
        cacheGrid.commands.push({ name: "save", icon: "k-i-save", text: "[resource_displayname[save]]" });
        cacheGrid.commands.push({ name: "remove", icon: "k-i-trash", text: "[resource_displayname[remove]]" });

        cacheGrid.toolbar = "<button class='btn btn-sm btn-primary' name='add'><span class='k-icon k-i-plus'></span> [resource_displayname[add]]</button>";

        cacheGrid.dataBound = function () {
            $("[name=save]", cacheGrid.gridElement).off("click").on("click", (e) => CommonCacheScripts.save(e, cacheGrid));
            $("[name=remove]", cacheGrid.gridElement).off("click").on("click", (e) => CommonCacheScripts.removeFromCache(e, cacheGrid));
            $("[name=viewVersions]", cacheGrid.gridElement).off("click").on("click", (e) => CommonCacheScripts.viewVersions(e, cacheGrid));
        };

        await cacheGrid.init();
        $("[name=add]", cacheGrid.gridElement).off("click").on("click", (e) => CommonCacheScripts.newScript(e, cacheGrid));
    },

    save: async function (e, grid) {
        var item = grid.dataItem($(e.currentTarget).closest("tr"));
        var dupe = JSON.parse(JSON.stringify(item));
        dupe.Entity.Key = dupe.Key;
        dupe.Json = JSON.stringify(dupe.Entity);
        delete dupe.Entity;

        await api.update("ContentManagement/CommonObject(" + item.Id + ")", dupe)
            .then(async () => {
                notification.success("[resource_displayname[saved]]");
                await api.get("RefreshCache");
                notification.success("[resource_displayname[rebuilt]]");
                grid.refresh();
            })
            .catch((err) => error(err));
    },

    newScript: async function (e, cacheGrid) {
        e.preventDefault();
        var newScriptDialog = new Dialog({ width: 520, height: "auto", title: "[resource_displayname[newscript]]" });
        newScriptDialog.template = $("[name=newScriptDialog]").html();

        newScriptDialog.events.create = async function () {
            var script = {
                Name: $("[name=name]", newScriptDialog.element).val(),
                Key: $("[name=key]", newScriptDialog.element).val(),
                Content: "",
                CreatedOn: (new Date()).toISOString(),
                LastUpdated: (new Date()).toISOString()
            };

            var commonObject = {
                Id: 0,
                Key: script.Key,
                Name: script.Name,
                CreatedOn: script.CreatedOn,
                LastUpdated: script.LastUpdated,
                Json: JSON.stringify(script),
                Type: "ContentManagement/Script",
                Culture: "",
                Version: 1
            };

            await api.add("ContentManagement/CommonObject", commonObject)
                .then(async () => {
                    notification.success("[resource_displayname[added]]");
                    await api.get("RefreshCache");
                    notification.success("[resource_displayname[rebuilt]]");
                    cacheGrid.refresh();
                })
                .catch((err) => error(err));

            newScriptDialog.events.close();
        };

        newScriptDialog.init();
    },

    removeFromCache: async function (e, grid) {
        var item = grid.kendoObject.dataItem($(e.currentTarget).closest("tr"));
        await api.destroy("ContentManagement/CommonObject(" + item.Id + ")")
            .then(async () => {
                notification.success("[resource_displayname[deleted]]");
                await api.get("RefreshCache");
                notification.success("[resource_displayname[rebuilt]]");
                grid.refresh();
            })
            .catch((err) => error(err));
    },

    viewVersions: async function (e, grid) {
        var item = grid.dataItem($(e.currentTarget).closest("tr"));
        var versionDialog = new Dialog({ title: "[resource_displayname[viewhistory]]", height: 800, width: 1200 });
        versionDialog.init(() => CommonCacheScripts.versionDialogInit(versionDialog, item));
    },

    versionDialogInit: async function (dialog, item) {
        let dataSource = (await api.get(
            "ContentManagement/CommonObject?$filter=Type eq 'ContentManagement/Script' and Name eq '" + item.Name + "'&$orderby=Version desc"
        )).value;

        var grid = new GridWidget(dialog.element, { data: dataSource, pageSize: 20 });
        grid.columns = [
            { field: "Version", title: "[resource_displayname[version]]" },
            { field: "LastUpdated", title: "[resource_displayname[lastupdated]]", width: 120, type: "date", format: "{0:g}" },
            { field: "LastUpdatedBy", title: "[resource_displayname[lastupdatedby]]", width: 200 }
        ];

        grid.groupable = false;
        grid.detailTemplate = `<div style='height:600px; padding-bottom: 40px;'>
            <div name='scriptEditor'><h4>[resource_displayname[recentscriptchanges]]</h4></div>
        </div>`;

        grid.detailExpand = function (e) {
            var versionedScript = JSON.parse(item.Json);
            var originalScript = JSON.parse(grid.dataItem(e.masterRow).Json);
            var expandContainer = $(e.detailRow);

            var originalScriptModel = monaco.editor.createModel(originalScript.Content, "text/javascript");
            var modifiedScriptModel = monaco.editor.createModel(versionedScript.Content, "text/javascript");

            var diffEditorScript = monaco.editor.createDiffEditor(
                $("[name=scriptEditor]", expandContainer)[0],
                { automaticLayout: true }
            );

            diffEditorScript.setModel({ original: originalScriptModel, modified: modifiedScriptModel });

            monaco.editor.createDiffNavigator(diffEditorScript, { followsCaret: true, ignoreCharChanges: true });
        };


        await grid.init();
    }
};
