  {
    "Name": "FullLogStream",
    "Key": "Logging",
    "ResourceKey": "Logging",
    "Script": "FullLogStream = {
    init: async function(app, container) {
        container = container || $(".component[name=FullLogStream]");
        if (typeof signalR === "undefined") {
            $("[name=logConsole]", container).append("<div class='message warn'>SignalR client is not loaded.</div>");
            return;
        }
        $("[name=level]", container).on("change", () => FullLogStream.applyLevelFilter(container));
        await FullLogStream.connectToLogHub(container);
    },

    connectToLogHub: async function(container) {
        var apps = (await api.get("ContentManagement/App?$select=Domain")).value;
        var domains = [...new Set(apps.map(app => app.Domain).filter(domain => domain))];
        await FullLogStream.connectToHub(container, async function(connection) {
            for (var domain of domains) {
                await connection.invoke("join", domain);
                await connection.invoke("ConsoleSend", "info", "Client Connected to Log Stream ", domain);
            }
        });
    },

    connectToHub: async function(container, callback) {
        var connection = new signalR.HubConnectionBuilder().withUrl(session.apiRoot + "Hubs/Logs").build();
        connection.on("ConsoleReceive", function(level, message) { FullLogStream.receiveMessage(container, level, message); });
        await connection.start();
        await callback(connection);
    },

    normaliseLevel: function(level) {
        level = (level || "info").toLowerCase();
        if (level === "information") return "info";
        if (level === "warning") return "warn";
        if (level === "critical") return "fatal";
        return level;
    },

    selectedLevels: function(container) {
        return $("[name=level]:checked", container).map(function() { return this.value; }).get();
    },

    applyLevelFilter: function(container) {
        var selected = FullLogStream.selectedLevels(container);
        $(".execConsole > .console > .message", container).each(function() {
            $(this).toggle(selected.indexOf($(this).data("level")) >= 0);
        });
    },

    receiveMessage: function(container, level, message) {
        var entry = { Level: FullLogStream.normaliseLevel(level), Timestamp: new Date(), Message: message };
        var htmlConsole = $(".execConsole > .console", container);
        var row = $(FullLogStream.buildMessage(entry));
        row.toggle(FullLogStream.selectedLevels(container).indexOf(entry.Level) >= 0);
        htmlConsole.append(row);
        if ($("input[name=autoScroll]", container).is(":checked")) {
            htmlConsole.scrollTop(htmlConsole.prop("scrollHeight"));
        }
    },

    buildMessage: function(logEntry) {
        var time = new Date(logEntry.Timestamp);
        var encoded = $("<div />").text(logEntry.Message).html();
        return "<div class='message " + logEntry.Level + "' data-level='" + logEntry.Level + "'>" +
            "<span class='level'>" + logEntry.Level.toUpperCase() + "</span>" +
            "<span class='time'>" + time.toLocaleTimeString() + "</span>" +
            "<pre class='message'>" + encoded + "</pre></div>";
    }
