  {
    "Name": "TenantManagement",
    "Key": "Security",
    "ResourceKey": "Security",
    "Script": "TenantManagement = {
    init: async function(app, container) {
        app = app || session.app;
        container = container || $(".component[name=TenantManagement]");
        api.addToMetaCache([{ Name: "Security", Types: [[meta[Security/Tenant]]] }]);

        var dataSource = await model.getDatasource({ endpoint: "Security/Tenant" });
        var grid = new GridWidget($("[name=tenants]", container), dataSource);
        grid.groupable = false;
        grid.filterable = true;
        grid.editable = true;
        grid.columns = [
            { field: "Id", title: "[resource_shortdisplayname[id]]" },
            { field: "Name", title: "[resource_shortdisplayname[name]]" },
            { field: "Description", title: "[resource_shortdisplayname[description]]" }
        ];
        grid.commands.push({ name: "save", icon: "k-i-save", text: "[resource_displayname[save]]" });
        grid.commands.push({ name: "destroy", icon: "k-i-trash", text: "[resource_displayname[delete]]" });
        grid.toolbar = "<button class='btn btn-sm btn-primary' name='add'><span class='k-icon k-i-plus'></span>[resource_displayname[add]]</button>";
        grid.detailTemplate = $("script[name=tenantDetails]", container).html();
        grid.detailExpand = (e) => TenantManagement.expand(e, app, grid);
        grid.dataBound = function() {
            $("[name=save]", grid.gridElement).off("click").on("click", (e) => TenantManagement.save(e, grid));
            $("[name=destroy]", grid.gridElement).off("click").on("click", (e) => TenantManagement.destroy(e, grid));
        };
        await grid.init();
        $("[name=add]", grid.gridElement).off("click").on("click", () => grid.dataSource().insert(0, { Id: "", Name: "", Description: "" }));
    },

    expand: async function(e, app, grid) {
        var tenant = grid.dataItem(e.masterRow);
        var container = $(e.detailRow);
        if (container.data("tenant-initialised")) return;
        container.data("tenant-initialised", true);
        var id = Guid();
        container.html(container.html().replaceAll("{ID}", id));
        await loadComponent($("[name=tenantRoles]", container), "SSORoleManagement");
        await SSORoleManagement.init(app, $(".component[name=SSORoleManagement]", container), tenant);
        await loadComponent($("[name=tenantApps]", container), "TenantAppManagement");
        await TenantAppManagement.init(app, $(".component[name=TenantAppManagement]", container), tenant);
    },

    save: async function(e, grid) {
        e.preventDefault();
        var tenant = grid.dataItem($(e.currentTarget).closest("tr"));
        if (tenant.isNew && tenant.isNew()) await api.add("Security/Tenant", tenant.toJSON());
        else await api.update("Security/Tenant('" + tenant.Id + "')", tenant.toJSON());
        notification.success("[resource_displayname[saved]]");
        grid.refresh();
    },

    destroy: function(e, grid) {
        e.preventDefault();
        var tenant = grid.dataItem($(e.currentTarget).closest("tr"));
        var dialog = new ConfirmDialog({ question: "[resource_displayname[AreYouSure]]", title: "[resource_displayname[AreYouSure]]", confirm: "[resource_displayname[Confirm]]", close: "[resource_displayname[Cancel]]" });
        dialog.events.confirm = async function() {
            await api.destroy("Security/Tenant('" + tenant.Id + "')");
            notification.success("[resource_displayname[deleted]]");
            dialog.events.close();
            grid.refresh();
        };
        dialog.init();
    }
};",
