<script>
    [script[DefaultResourcing]]
    [script[KendoCultures]]
    type.dateFormat = "[resource_displayname[dateformat]]";
    if (!type.dateFormat || type.dateFormat.toLowerCase() === "dateformat") { type.dateFormat = "yyyy MMMM dd"; }
    type.shortDateFormat = "[resource_displayname[shortdateformat]]";
    if (!type.shortDateFormat || type.shortDateFormat.toLowerCase() === "shortdateformat") { type.shortDateFormat = "yyyy-MM-dd"; }
    type.dateAndTimeFormat = "[resource_displayname[dateandtimeformat]]";
    if (!type.dateAndTimeFormat || type.dateAndTimeFormat.toLowerCase() === "dateandtimeformat") { type.dateAndTimeFormat = "yyyy MMMM dd HH:mm"; }
    type.timeFormat = "[resource_displayname[timeformat]]";
    if (!type.timeFormat || type.timeFormat.toLowerCase() === "timeformat") { type.timeFormat = "HH:mm"; }
    type.moneyFormat = "[resource_displayname[moneyformat]]";
    type.aggregateMoneyFormat = "[resource_displayname[aggregateMoneyFormat]]";

    initContent();
    kendo.setDefaults('iconType', 'svg');

    const targetNode = document.body;
    const observerConfig = { attributes: true, childList: true, subtree: true };
    const observer = new MutationObserver(initIcons);
    observer.observe(targetNode, observerConfig);

    function initIcons() {
        observer.disconnect();

        $(".k-icon:not(.k-svg-icon):not(.k-font-icon)").each(function() {
            var iconName = $(this).attr('class').split(' ').filter(function(cls) {
                return cls !== 'k-icon';
            })[0].replace(/^k-i-/, "").replace("source-code", "code");

            var svgIcon = kendo.ui.icon({ icon: iconName, type: 'svg' });

            if(svgIcon != `<span class="k-icon k-svg-icon" aria-hidden="true"></span>`) {
                $(this).replaceWith(svgIcon);
            }
        });

        observer.observe(targetNode, observerConfig);
    }

    function highlightCSharpSamples() {
        const keywords = new Set(["abstract","as","async","await","base","bool","break","byte","case","catch","char","class","const","continue","decimal","default","delegate","do","double","else","enum","event","explicit","extern","false","finally","fixed","float","for","foreach","if","implicit","in","int","interface","internal","is","lock","long","namespace","new","null","object","operator","out","override","params","private","protected","public","readonly","record","ref","return","sbyte","sealed","short","sizeof","stackalloc","static","string","struct","switch","this","throw","true","try","typeof","uint","ulong","unchecked","unsafe","ushort","using","var","virtual","void","volatile","while","with","yield"]);
        const knownTypes = new Set(["IServiceCollection","WebApplication","WebApplicationBuilder","Task","ValueTask","IEventHub","CoreDataContext","ICompletionProviderService","IAgentOrchestrationService","IModelManagerService"]);
        const escapeHtml = value => value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
        const tokenPattern = /(\/\*[\s\S]*?\*\/|\/\/.*?$|@?"(?:""|\\.|[^"\\])*"|'(?:\\.|[^'\\])'|\b\d+(?:\.\d+)?\b|\b[A-Za-z_][A-Za-z0-9_]*\b)/gm;

        document.querySelectorAll("code.language-csharp:not([data-highlighted])").forEach(code => {
            const source = code.textContent;
            let output = "";
            let cursor = 0;

            source.replace(tokenPattern, (token, _capture, offset) => {
                output += escapeHtml(source.slice(cursor, offset));
                let className = "";
                if (token.startsWith("//") || token.startsWith("/*")) className = "syntax-comment";
                else if (token.startsWith('"') || token.startsWith('@"') || token.startsWith("'")) className = "syntax-string";
                else if (/^\d/.test(token)) className = "syntax-number";
                else if (keywords.has(token)) className = "syntax-keyword";
                else if (knownTypes.has(token) || /^[A-Z][A-Za-z0-9_]*$/.test(token)) className = "syntax-type";
                output += className ? `<span class="${className}">${escapeHtml(token)}</span>` : escapeHtml(token);
                cursor = offset + token.length;
                return token;
            });

            output += escapeHtml(source.slice(cursor));
            code.innerHTML = output;
            code.dataset.highlighted = "true";
        });
    }

    queueMicrotask(highlightCSharpSamples);</script>",
