@media (max-width:767.98px){.docs-nav-grid[data-columns="2"],.docs-nav-grid[data-columns="3"]{grid-template-columns:1fr}}
@media (max-width:991.98px){.docs-sidebar{position:static;top:auto}}

.docs-nav-scope-grid {
  gap: 1.25rem;
}

.docs-nav-scope {
  position: relative;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  padding: 1.35rem 1.4rem 1.2rem 1.65rem;
  border: 1px solid rgba(20, 42, 72, .16);
  border-left: 3px solid #0e6fae;
  border-radius: 6px;
  background: #fff;
  box-shadow: 0 8px 20px rgba(20, 42, 72, .07);
  transition: transform .18s ease, border-color .18s ease, box-shadow .18s ease;
}

.docs-nav-scope:hover {
  transform: translateY(-2px);
  border-color: rgba(14, 111, 174, .42);
  box-shadow: 0 12px 26px rgba(20, 42, 72, .11);
}

.docs-nav-title {
  margin: 0 0 .75rem;
  font-family: inherit;
  font-size: 1.05rem;
  line-height: 1.35;
}

.docs-nav-title a {
  color: #142a48;
  text-decoration: none;
}

.docs-nav-title a:hover,
.docs-nav-title a:focus-visible {
  color: #0e6fae;
  text-decoration: underline;
  text-underline-offset: .2em;
}

.docs-nav-description {
  flex: 1 1 auto;
  margin: 0 0 1rem 1.2rem;
  color: #40576b;
}

.docs-nav-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 2rem;
  margin-top: auto;
  padding-left: .15rem;
}

.docs-nav-actions {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: flex-end;
  align-items: flex-end;
  width: 100%;
  margin-top: auto;
  margin-left: auto;
  padding-top: calc(var(--site-gap) * 1.5);
  padding-right: 0;
}

.docs-nav-command {
  display: inline-flex;
  align-items: center;
  gap: .08rem;
  padding: .42rem .68rem;
  border: 1px solid rgba(14, 111, 174, .28);
  border-radius: 4px;
  background: #f2f9fd;
  color: #0e6fae;
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace;
  font-size: var(--bs-body-font-size);
  font-weight: 700;
  line-height: 1;
  text-decoration: none;
}

.docs-nav-command-call { color: #6542a6; }
.docs-nav-command-arrow {
  margin-left: .38rem;
  transition: transform .18s ease;
}

.docs-nav-command:hover,
.docs-nav-command:focus-visible {
  border-color: #0e6fae;
  background: #e4f4fd;
  color: #0b5788;
  text-decoration: none;
}

.docs-nav-command:hover .docs-nav-command-arrow,
.docs-nav-command:focus-visible .docs-nav-command-arrow {
  transform: translateX(3px);
}

@media (max-width: 575.98px) {
  .docs-nav-scope { padding-left: 1.25rem; }
  .docs-nav-description,
  .docs-nav-actions { margin-left: 0; }
}

