.semantic-image-block::before{content:"{";margin-bottom:.5rem}
.semantic-image-block::after{content:"}";margin-top:.5rem}
.semantic-image-block>img{margin:0!important}
p.semantic-image-host{max-width:none;margin:0;padding-left:0}
p.semantic-image-host::before,p.semantic-image-host::after{content:none}

/* Quiet heading weight and baseline-aligned inline semantics. */
h1{font-weight:400!important}h2,h3,h4,h5,h6{font-weight:700!important}
h1::before,h1::after,h2::before,h2::after,h3::before,h3::after,h4::before,h4::after,h5::before,h5::after,h6::before,h6::after,.docs-nav-title::before,.docs-nav-title::after{font-weight:400}
